import{_ as o,l as s,o as e,c as i,v as t,p as l,x as n,d as S,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"2SLS 与过度识别","description":"","frontmatter":{"title":"2SLS 与过度识别","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/2sls-overid.md","filePath":"econ/2sls-overid.md","lastUpdated":1789023840000}'),E={name:"econ/2sls-overid.md"};function c(m,a,h,_,A,L){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="_2sls-与过度识别" tabindex="-1">2SLS 与过度识别 <a class="header-anchor" href="#_2sls-与过度识别" aria-label="Permalink to &quot;2SLS 与过度识别&quot;">​</a></h1><div class="epigraph"><p>多个工具时，两阶段最小二乘把第一阶段拟合成最优线性组合；过度识别检验问的是这些工具是否指向同一个 $\\beta$，不是单条排除已经证实。</p><footer>—— Theil 2SLS；Sargan, The Estimation of Economic Relationships Using Instrumental Variables, Econometrica 1958；Hansen, Large Sample Properties of Generalized Method of Moments, Econometrica 1982</footer></div><p><a href="/econ/iv-weak-instruments">上一课</a>在恰好识别下写出 Wald 比，并警告弱工具。本课缺口是多个 \\(Z\\)：2SLS 如何加权，以及过度识别（overid）能检验什么、不能检验什么。<a href="/econ/gmm-econ">GMM</a>下一课把矩条件写清；准实验更后再换设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(X\\) 内生，\\(Z\\) 是 \\(L\\times 1\\)，\\(L\\gt 1\\)。每个工具单独给一个 IV 估计，一般不一致（有限样本更不用说）。2SLS：第一阶段用全部 \\(Z\\)（加外生控制）拟合 \\(\\hat X\\)，第二阶段 \\(Y\\) 对 \\(\\hat X\\) 回归。它等价于 GMM 在同方差下用最优权重。缺口是：若各 \\(Z\\) 的 LATE 不同，2SLS 估的是工具特定权重的混合，过度识别拒绝可能是异质而不是「内生」。</p><p>Sargan / Hansen \\(J\\)：过度识别约束的二次型。不拒绝不能证明排除成立——只是工具之间的隐含 \\(\\beta\\) 够接近。拒绝则要么排除失败，要么模型（常数 \\(\\beta\\)、线性）错。</p><p><span class="marginnote">恰好识别时 \\(J\\) 没有自由度，排除仍不可检验。过度识别检验的是工具之间的一致性，不是与「真排除」的距离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(P_Z\\) 为 \\(Z\\) 上的投影。2SLS \\(= (X&#39;P_Z X)^{-1}X&#39;P_Z Y\\)。LIML 在弱工具与多工具时偏误往往小于 2SLS；Fuller 修正是常用稳健变体。异方差下用 Hansen \\(J\\) 而不是 Sargan。聚类时权重与 \\(J\\) 都要换成聚类协方差。</p>',9)),(e(),l(p,null,{default:n(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ZS%5B%22%E5%A4%9A%E4%B8%AA%20Z%22%5D%20--%3E%20FS%5B%22%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%E6%8A%95%E5%BD%B1%22%5D%0A%20%20FS%20--%3E%20TSLS%5B%222SLS%20%2F%20GMM%22%5D%0A%20%20TSLS%20--%3E%20J%5B%22Hansen%E2%80%93Sargan%20J%22%5D%0A%20%20J%20--%3E%20SAME%5B%22%E4%B8%8D%E6%8B%92%E7%BB%9D%3A%20%E5%B7%A5%E5%85%B7%E5%BD%BC%E6%AD%A4%E4%B8%80%E8%87%B4%22%5D%0A%20%20J%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%3A%20%E6%8E%92%E9%99%A4%E6%88%96%E5%B8%B8%E6%95%B0%20%CE%B2%20%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>弱工具加多工具：2SLS 有限样本偏向 OLS 更明显。诊断仍用第一阶段（Kleibergen–Paap）、Anderson–Rubin、条件 LR，不要只报 2SLS 点估计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把 \\(Z\\) 张成的外生变异投影到 \\(X\\) 上，再用这段预测值当「清洗过的回归元」。同方差时，这个线性组合在 IV 类中渐近有效。异质 LATE 下，每个 \\(Z\\) 对应不同编译器群体，2SLS 权重由第一阶段拟合给出——与 ATE 无必然关系。\\(J\\) 拒绝可以是「义务教育季度与学费减免推动的不是同一群人」。</p><p>与上一课弱工具：工具很多但每个都弱，\\(J\\) 的名义水平也会坏。先强度、再过度识别，顺序不要倒。</p><p><span class="marginnote">Hansen 1982 的 GMM 把 2SLS 放进矩条件：\\(\\mathbb{E}[Z u]=0\\)。最优权重是 \\(Zu\\) 的协方差之逆。\\(J\\) 是过度约束的 GMM 目标函数值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 \\(J\\) 的 \\(p\\gt 0.05\\) 写成论文的识别证明。不引入三阶段、控制函数的完整菜单——离散内生下一单元再写。量化栏公司金融里「滞后工具」常弱且排除可疑，本课只给语言，不重做那些表。下一课 GMM 把 2SLS 收进矩；准实验更后才把识别换成时间上的政策差。</p><p>后课默认：多个工具时报告 2SLS / LIML、第一阶段、以及 \\(J\\) 的解释（异质对排除）。不要把过度识别当成恰好识别排除的替代证明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2SLS = 用 \\(Z\\) 投影清洗 \\(X\\)；同方差 GMM 的特例。</li><li>\\(J\\) 检验工具之间是否指向同一 \\(\\beta\\)，不证实单条排除。</li><li>异质 LATE 下拒绝可以是权重不同，不是一定「工具坏了」。</li><li>弱加多工具：优先 LIML / AR，而不是堆 \\(Z\\)。</li><li>出处：Theil 2SLS；Sargan, <em>Econometrica</em> 1958；Hansen, <em>Econometrica</em> 1982；Angrist and Pischke, <em>Mostly Harmless</em>。</li></ul>',10))])}const f=o(E,[["render",c]]);export{u as __pageData,f as default};
